import { pool } from '../../shared/db/connection';
import { Employee, IEmployeeRepository } from './employee.model';

interface EmployeeRow {
  id: string;
  employee_number: string;
  first_name: string;
  last_name: string;
  email: string;
  manager_id: string | null;
  department: string | null;
  hire_date: Date;
  termination_date: Date | null;
  employment_status: string;
  created_at: Date;
  updated_at: Date;
  deleted_at: Date | null;
}

function mapRowToEmployee(row: EmployeeRow): Employee {
  return {
    id: row.id,
    employeeNumber: row.employee_number,
    firstName: row.first_name,
    lastName: row.last_name,
    email: row.email,
    managerId: row.manager_id,
    department: row.department,
    hireDate: row.hire_date,
    terminationDate: row.termination_date,
    employmentStatus: row.employment_status as Employee['employmentStatus'],
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    deletedAt: row.deleted_at,
  };
}

const COLUMN_MAP: Record<string, string> = {
  employeeNumber: 'employee_number',
  firstName: 'first_name',
  lastName: 'last_name',
  email: 'email',
  managerId: 'manager_id',
  department: 'department',
  hireDate: 'hire_date',
  terminationDate: 'termination_date',
  employmentStatus: 'employment_status',
};

export class PgEmployeeRepository implements IEmployeeRepository {
  async findById(id: string): Promise<Employee | null> {
    const result = await pool.query<EmployeeRow>(
      'SELECT * FROM employees WHERE id = $1 AND deleted_at IS NULL',
      [id],
    );
    if (result.rows.length === 0) {
      return null;
    }
    return mapRowToEmployee(result.rows[0]);
  }

  async findByEmployeeNumber(employeeNumber: string): Promise<Employee | null> {
    const result = await pool.query<EmployeeRow>(
      'SELECT * FROM employees WHERE employee_number = $1 AND deleted_at IS NULL',
      [employeeNumber],
    );
    if (result.rows.length === 0) {
      return null;
    }
    return mapRowToEmployee(result.rows[0]);
  }

  async findAll(): Promise<Employee[]> {
    const result = await pool.query<EmployeeRow>(
      'SELECT * FROM employees WHERE deleted_at IS NULL',
    );
    return result.rows.map(mapRowToEmployee);
  }

  async create(
    employee: Omit<Employee, 'id' | 'createdAt' | 'updatedAt' | 'deletedAt'>,
  ): Promise<Employee> {
    const result = await pool.query<EmployeeRow>(
      `INSERT INTO employees (
        employee_number, first_name, last_name, email,
        manager_id, department, hire_date, termination_date, employment_status
      ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
      RETURNING *`,
      [
        employee.employeeNumber,
        employee.firstName,
        employee.lastName,
        employee.email,
        employee.managerId,
        employee.department,
        employee.hireDate,
        employee.terminationDate,
        employee.employmentStatus,
      ],
    );
    return mapRowToEmployee(result.rows[0]);
  }

  async update(id: string, data: Partial<Employee>): Promise<Employee | null> {
    const keys = Object.keys(data).filter(
      (k) =>
        data[k as keyof typeof data] !== undefined &&
        COLUMN_MAP[k] !== undefined,
    );

    if (keys.length === 0) {
      const existing = await this.findById(id);
      return existing;
    }

    const setClauses = keys.map(
      (key, index) => `${COLUMN_MAP[key]} = $${index + 2}`,
    );
    const values = keys.map((key) => data[key as keyof typeof data]);

    const result = await pool.query<EmployeeRow>(
      `UPDATE employees SET ${setClauses.join(', ')}, updated_at = NOW() WHERE id = $1 AND deleted_at IS NULL RETURNING *`,
      [id, ...values],
    );

    if (result.rows.length === 0) {
      return null;
    }
    return mapRowToEmployee(result.rows[0]);
  }

  async softDelete(id: string): Promise<void> {
    await pool.query(
      'UPDATE employees SET deleted_at = NOW() WHERE id = $1',
      [id],
    );
  }
}

import { pool } from '../../shared/db/connection';
import { BalanceStatus } from '../../shared/types';
import { Balance, IBalanceRepository } from './balance.model';

interface BalanceRow {
  id: string;
  employee_id: string;
  leave_type: string;
  total_entitlement: number;
  used_days: number;
  remaining_days: number;
  fiscal_year: number;
  status: string;
  created_at: Date;
  updated_at: Date;
}

function mapRowToBalance(row: BalanceRow): Balance {
  return {
    id: row.id,
    employeeId: row.employee_id,
    leaveType: row.leave_type,
    totalEntitlement: row.total_entitlement,
    usedDays: row.used_days,
    remainingDays: row.remaining_days,
    fiscalYear: row.fiscal_year,
    status: row.status as BalanceStatus,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

const COLUMN_MAP: Record<string, string> = {
  employeeId: 'employee_id',
  leaveType: 'leave_type',
  totalEntitlement: 'total_entitlement',
  usedDays: 'used_days',
  remainingDays: 'remaining_days',
  fiscalYear: 'fiscal_year',
  status: 'status',
};

export class PgBalanceRepository implements IBalanceRepository {
  async findByEmployeeId(employeeId: string): Promise<Balance[]> {
    const result = await pool.query<BalanceRow>(
      'SELECT * FROM balances WHERE employee_id = $1',
      [employeeId],
    );
    return result.rows.map(mapRowToBalance);
  }

  async findByEmployeeIdAndLeaveType(
    employeeId: string,
    leaveType: string,
  ): Promise<Balance | null> {
    const result = await pool.query<BalanceRow>(
      'SELECT * FROM balances WHERE employee_id = $1 AND leave_type = $2',
      [employeeId, leaveType],
    );
    if (result.rows.length === 0) {
      return null;
    }
    return mapRowToBalance(result.rows[0]);
  }

  async findByEmployeeIdAndFiscalYear(
    employeeId: string,
    fiscalYear: number,
  ): Promise<Balance[]> {
    const result = await pool.query<BalanceRow>(
      'SELECT * FROM balances WHERE employee_id = $1 AND fiscal_year = $2',
      [employeeId, fiscalYear],
    );
    return result.rows.map(mapRowToBalance);
  }

  async create(
    balance: Omit<Balance, 'id' | 'createdAt' | 'updatedAt'>,
  ): Promise<Balance> {
    const result = await pool.query<BalanceRow>(
      `INSERT INTO balances (
        employee_id, leave_type, total_entitlement,
        used_days, remaining_days, fiscal_year, status
      ) VALUES ($1, $2, $3, $4, $5, $6, $7)
      RETURNING *`,
      [
        balance.employeeId,
        balance.leaveType,
        balance.totalEntitlement,
        balance.usedDays,
        balance.remainingDays,
        balance.fiscalYear,
        balance.status,
      ],
    );
    return mapRowToBalance(result.rows[0]);
  }

  async update(
    id: string,
    data: Partial<Balance>,
  ): Promise<Balance | null> {
    const keys = Object.keys(data).filter(
      (k) =>
        data[k as keyof typeof data] !== undefined &&
        COLUMN_MAP[k] !== undefined,
    );

    if (keys.length === 0) {
      const existing = await this.findById(id);
      return existing;
    }

    const setClauses = keys.map(
      (key, index) => `${COLUMN_MAP[key]} = $${index + 2}`,
    );
    const values = keys.map((key) => data[key as keyof typeof data]);

    const result = await pool.query<BalanceRow>(
      `UPDATE balances SET ${setClauses.join(', ')}, updated_at = NOW() WHERE id = $1 RETURNING *`,
      [id, ...values],
    );

    if (result.rows.length === 0) {
      return null;
    }
    return mapRowToBalance(result.rows[0]);
  }

  async deductDays(id: string, days: number): Promise<Balance | null> {
    const result = await pool.query<BalanceRow>(
      `UPDATE balances
       SET remaining_days = remaining_days - $2,
           used_days = used_days + $2,
           status = CASE WHEN remaining_days - $2 <= 0 THEN 'exhausted' ELSE status END,
           updated_at = NOW()
       WHERE id = $1
       RETURNING *`,
      [id, days],
    );

    if (result.rows.length === 0) {
      return null;
    }
    return mapRowToBalance(result.rows[0]);
  }

  private async findById(id: string): Promise<Balance | null> {
    const result = await pool.query<BalanceRow>(
      'SELECT * FROM balances WHERE id = $1',
      [id],
    );
    if (result.rows.length === 0) {
      return null;
    }
    return mapRowToBalance(result.rows[0]);
  }
}

import {
  Balance,
  BalanceNotFoundError,
  IBalanceRepository,
  IBalanceService,
  InsufficientBalanceError,
} from './balance.model';

export class BalanceService implements IBalanceService {
  constructor(private readonly repository: IBalanceRepository) {}

  async getBalance(
    employeeId: string,
    leaveType: string,
  ): Promise<Balance | null> {
    return this.repository.findByEmployeeIdAndLeaveType(employeeId, leaveType);
  }

  async getBalances(employeeId: string): Promise<Balance[]> {
    return this.repository.findByEmployeeId(employeeId);
  }

  async hasSufficientBalance(
    employeeId: string,
    leaveType: string,
    requestedDays: number,
  ): Promise<boolean> {
    const balance = await this.repository.findByEmployeeIdAndLeaveType(
      employeeId,
      leaveType,
    );
    if (balance === null) {
      return false;
    }
    return balance.remainingDays >= requestedDays;
  }

  async deductBalance(
    employeeId: string,
    leaveType: string,
    days: number,
  ): Promise<Balance> {
    const balance = await this.repository.findByEmployeeIdAndLeaveType(
      employeeId,
      leaveType,
    );

    if (balance === null) {
      throw new BalanceNotFoundError(
        `Balance not found for employee ${employeeId} and leave type ${leaveType}`,
      );
    }

    if (balance.remainingDays < days) {
      throw new InsufficientBalanceError(
        `Insufficient balance: requested ${days} days but only ${balance.remainingDays} remaining`,
      );
    }

    const updated = await this.repository.deductDays(balance.id, days);
    if (updated === null) {
      throw new BalanceNotFoundError(
        `Balance not found for id ${balance.id}`,
      );
    }
    return updated;
  }
}

import { FastifyReply, FastifyRequest } from 'fastify';
import { BalanceService } from './balance.service';

export class BalanceController {
  constructor(private readonly balanceService: BalanceService) {}

  getBalance = async (
    request: FastifyRequest<{ Params: { employeeId: string; leaveType: string } }>,
    reply: FastifyReply,
  ): Promise<void> => {
    try {
      const { employeeId, leaveType } = request.params;
      const balance = await this.balanceService.getBalance(employeeId, leaveType);

      if (balance === null) {
        await reply.status(404).send({
          error: 'Not Found',
          message: `Balance not found for employee ${employeeId} and leave type ${leaveType}`,
        });
        return;
      }

      await reply.status(200).send(balance);
    } catch (error) {
      request.log.error(error);
      await reply.status(500).send({ error: 'Internal Server Error' });
    }
  };

  getBalances = async (
    request: FastifyRequest<{ Params: { employeeId: string } }>,
    reply: FastifyReply,
  ): Promise<void> => {
    try {
      const { employeeId } = request.params;
      const balances = await this.balanceService.getBalances(employeeId);

      await reply.status(200).send(balances);
    } catch (error) {
      request.log.error(error);
      await reply.status(500).send({ error: 'Internal Server Error' });
    }
  };
}

import { FastifyInstance } from 'fastify';
import { BalanceController } from './balance.controller';
import { BalanceService } from './balance.service';
import { PgBalanceRepository } from './balance.repository';

export async function balanceRoutes(fastify: FastifyInstance): Promise<void> {
  const repository = new PgBalanceRepository();
  const service = new BalanceService(repository);
  const controller = new BalanceController(service);

  fastify.get(
    '/balance/:employeeId/:leaveType',
    controller.getBalance,
  );

  fastify.get(
    '/balance/:employeeId',
    controller.getBalances,
  );
}

import { pool } from '../../shared/db/connection';
import { AuditLog, IAuditLogRepository } from './audit-log.model';

interface AuditLogRow {
  id: string;
  entity_type: string;
  entity_id: string;
  action: string;
  performed_by: string;
  changes: Record<string, unknown>;
  created_at: Date;
}

function mapRowToAuditLog(row: AuditLogRow): AuditLog {
  return {
    id: row.id,
    entityType: row.entity_type,
    entityId: row.entity_id,
    action: row.action,
    performedBy: row.performed_by,
    changes: row.changes,
    createdAt: row.created_at,
  };
}

export class PgAuditLogRepository implements IAuditLogRepository {
  async findByEntity(
    entityType: string,
    entityId: string,
  ): Promise<AuditLog[]> {
    const result = await pool.query<AuditLogRow>(
      'SELECT * FROM audit_logs WHERE entity_type = $1 AND entity_id = $2 ORDER BY created_at DESC',
      [entityType, entityId],
    );
    return result.rows.map(mapRowToAuditLog);
  }

  async create(
    entry: Omit<AuditLog, 'id' | 'createdAt'>,
  ): Promise<AuditLog> {
    const result = await pool.query<AuditLogRow>(
      `INSERT INTO audit_logs (
        entity_type, entity_id, action, performed_by, changes
      ) VALUES ($1, $2, $3, $4, $5)
      RETURNING *`,
      [
        entry.entityType,
        entry.entityId,
        entry.action,
        entry.performedBy,
        entry.changes,
      ],
    );
    return mapRowToAuditLog(result.rows[0]);
  }

  async findAll(
    filters?: {
      entityType?: string;
      performedBy?: string;
      fromDate?: Date;
      toDate?: Date;
    },
  ): Promise<AuditLog[]> {
    const conditions: string[] = [];
    const values: unknown[] = [];
    let paramIndex = 1;

    if (filters?.entityType !== undefined) {
      conditions.push(`entity_type = $${paramIndex}`);
      values.push(filters.entityType);
      paramIndex++;
    }

    if (filters?.performedBy !== undefined) {
      conditions.push(`performed_by = $${paramIndex}`);
      values.push(filters.performedBy);
      paramIndex++;
    }

    if (filters?.fromDate !== undefined) {
      conditions.push(`created_at >= $${paramIndex}`);
      values.push(filters.fromDate);
      paramIndex++;
    }

    if (filters?.toDate !== undefined) {
      conditions.push(`created_at <= $${paramIndex}`);
      values.push(filters.toDate);
      paramIndex++;
    }

    const whereClause =
      conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';

    const result = await pool.query<AuditLogRow>(
      `SELECT * FROM audit_logs ${whereClause} ORDER BY created_at DESC`,
      values,
    );
    return result.rows.map(mapRowToAuditLog);
  }
}

import { PgBalanceRepository } from '../../../../src/modules/balance/balance.repository';
import { Balance } from '../../../../src/modules/balance/balance.model';
import { BalanceStatus } from '../../../../src/shared/types';

jest.mock('../../../../src/shared/db/connection', () => ({
  pool: {
